//! Independent paid service, reach/event/World quantity flow and life boundaries.
use gielinor_world::{inventory::Item,npc::{Npc,Restrict,BlockWalk},npc_interaction::{Handler,Event},tanning::{Recipe,Request},simulation::{World,PlayerData,ActorId,WorldEvent,Action},stats::Stats,hits::{Hit,Target,Style},CoordGrid};
fn fixture(kind:u16,coins:i32,member:bool)->(World,ActorId,gielinor_world::simulation::NpcId,Request){let mut w=World::default();w.collision.allocate(3200,3200,0);w.object_types.stackable.insert(995);w.tanning.insert(kind,vec![Recipe{input:1739,output:1741,cost:1,members:false},Recipe{input:1739,output:1743,cost:3,members:false}]);w.npc_handlers.insert((kind,3),Handler::Tanning);let mut options=gielinor_world::npc_options::Definition::default();options.operations[2]=Some("Trade".into());w.npc_options.types.insert(kind,options);let target=w.spawn_npc(Npc::new(kind,CoordGrid::new(3201,3200,0).unwrap(),1,Restrict::NoMove,BlockWalk::None).unwrap()).unwrap();let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_current(12,0);let mut data=PlayerData::new(1,"Independent paid tanning".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);for slot in 0..27{data.inventory.restore_slot(slot,Some(Item{id:1739,count:1,vars:0})).unwrap();}data.inventory.restore_slot(27,Some(Item{id:if coins>0{995}else{1931},count:if coins>0{coins}else{1},vars:0})).unwrap();w.queue_login(1,data).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();w.drain_events();w.submit(a,Action::OperateNpc{target,operation:3,control:false}).unwrap();w.tick().unwrap();assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::NpcInteraction{actor,event:Event::Tanning(n)} if *actor==a && *n==target)));let req=w.tanning_request(a,target).unwrap();assert_eq!(req.recipes().count(),2);(w,a,target,req)}
#[test]fn one_hundred_sixty_paid_batch_and_world_token_controls(){let mut n=0;for kind in[3231,5809]{for index in 0..2{let(cost,out)=if index==0{(1,1741)}else{(3,1743)};for coins in[0,cost,5*cost-1,i32::MAX]{for count in[0,1,5,28,i32::MAX]{for member in[false,true]{let(mut w,a,_,req)=fixture(kind,coins,member);let before=w.data(a).unwrap().clone();let token=w.start_quantity_dialog(a).unwrap();assert!(w.resume_quantity_dialog(a,token).unwrap());w.complete_tanning(a,req,index,count).unwrap();assert!(!w.resume_quantity_dialog(a,token).unwrap());let made=count.min(27).min(coins/cost).max(0);let mut expected=before.inventory.clone();if made>0{for slot in 0..made{expected.restore_slot(slot as usize,Some(Item{id:out,count:1,vars:0})).unwrap();}let remaining=coins-cost*made;expected.restore_slot(27,if remaining>0{Some(Item{id:995,count:remaining,vars:0})}else{None}).unwrap();}assert_eq!(w.data(a).unwrap().inventory,expected,"kind{kind} index{index} coins{coins} count{count} member{member}");assert_eq!(w.data(a).unwrap().stats,before.stats);for _ in 0..4{w.tick().unwrap();}assert_eq!(w.data(a).unwrap().inventory,expected);assert_eq!(w.data(a).unwrap().stats,before.stats);n+=1;}}}}}assert_eq!(n,160);}
fn life(kind:u16,index:usize,death:bool,pending:bool){let(mut w,a,target,old)=fixture(kind,100,true);let token=if pending{Some(w.start_quantity_dialog(a).unwrap())}else{None};if death{w.queue_hit(Target::Player(a),Hit{display:None,source:None,style:Style::Typeless,damage:20},1).unwrap();w.tick().unwrap();assert_eq!(w.data(a).unwrap().stats.current(3),0);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::DeathRequested(_))));w.data_mut(a).unwrap().stats.set_current(3,10);}else{w.data_mut(a).unwrap().stats.set_current(3,0);}let before=w.data(a).unwrap().clone();let request=if pending{Some(old)}else{w.tanning_request(a,target).ok()};if let Some(req)=request{let token=token.or_else(||w.start_quantity_dialog(a).ok());if let Some(token)=token{if w.resume_quantity_dialog(a,token).unwrap_or(false){let _=w.complete_tanning(a,req,index,5);}}}for _ in 0..4{w.tick().unwrap();}let d=w.data(a).unwrap();println!("PG_TANNING_LIFE npc={kind} choice={index} death={death} pending={pending} inventory_unchanged={} coin_count={} xp_delta={}",d.inventory==before.inventory,d.inventory.get(27).map_or(0,|i|i.count),d.stats.fine_xp(12)-before.stats.fine_xp(12));assert_eq!(d.inventory,before.inventory);assert_eq!(d.stats,before.stats);}
macro_rules! life_case{($name:ident,$npc:expr,$index:expr,$death:expr,$pending:expr)=>{#[test]fn $name(){life($npc,$index,$death,$pending)}};}
life_case!(ellis_soft_zero_before_request,3231,0,false,false);
life_case!(ellis_soft_death_before_request,3231,0,true,false);
life_case!(ellis_soft_zero_pending,3231,0,false,true);
life_case!(ellis_soft_death_pending,3231,0,true,true);
life_case!(ellis_hard_zero_before_request,3231,1,false,false);
life_case!(ellis_hard_death_before_request,3231,1,true,false);
life_case!(ellis_hard_zero_pending,3231,1,false,true);
life_case!(ellis_hard_death_pending,3231,1,true,true);
life_case!(guild_soft_zero_before_request,5809,0,false,false);
life_case!(guild_soft_death_before_request,5809,0,true,false);
life_case!(guild_soft_zero_pending,5809,0,false,true);
life_case!(guild_soft_death_pending,5809,0,true,true);
life_case!(guild_hard_zero_before_request,5809,1,false,false);
life_case!(guild_hard_death_before_request,5809,1,true,false);
life_case!(guild_hard_zero_pending,5809,1,false,true);
life_case!(guild_hard_death_pending,5809,1,true,true);
